// Mark Reindex: помечает запуск переиндексации (по расписанию или по запросу).
const input = $input.first().json;
return [{ json: { op: 'reindex', via: input.body !== undefined || input.headers !== undefined ? 'webhook' : 'schedule', request: input } }];

// ================= НАСТРОЙКИ АГЕНТА =================
// Меняйте только значения справа от двоеточия. Подробно — docs/02-setup.md.
const config = {
  // Чья это база — агент отвечает от имени команды
  company: 'Название компании',
  audience: 'сотрудники компании', // кто задаёт вопросы: сотрудники, клиенты, партнёры
  owner_contact: 'Отдел знаний, @username', // к кому идти, если ответа нет

  // Источники: папка Google Drive и лист Sources (ссылки на страницы)
  drive_folder_id: 'ВСТАВЬТЕ_ID_ПАПКИ',
  spreadsheet_id: 'ВСТАВЬТЕ_ID_ТАБЛИЦЫ',

  // Имя индекса в Simple Vector Store. Меняйте, если в одном n8n несколько баз.
  index_key: 'kb_main',

  // Нарезка документов
  chunk_size: 1200,    // символов в одном фрагменте
  chunk_overlap: 200,  // перекрытие соседних фрагментов
  max_doc_chars: 300000, // длиннее — документ обрезается при индексации

  // Поиск
  search_top_k: 8,     // сколько фрагментов достаёт поиск
  max_passages: 5,     // сколько фрагментов уходит модели
  min_score: 0.35,     // ниже — «в документах нет» (0–1, см. docs/04-search.md)

  // Telegram-чат команды: передачи человеку, пробелы в базе, отчёты переиндексации
  team_chat_id: 'ВСТАВЬТЕ_ID_ЧАТА',

  // Кто может спрашивать в Telegram: числовые ID пользователей. Пусто — никто.
  // Бот отвечает незнакомцу его ID — так его проще добавить.
  allowed_telegram_ids: [],

  // Ключ, без которого вебхуки не отвечают. Длинная случайная строка.
  agent_token: 'ЗАМЕНИТЕ_НА_ДЛИННУЮ_СЛУЧАЙНУЮ_СТРОКУ',

  // Ограничения
  max_message_chars: 2000,
  rate_limit_messages: 30,
  rate_limit_minutes: 10,
  daily_agent_runs: 2000,
  handoff_pause_minutes: 30,

  // Служебная метка в системной инструкции. Если она появится в ответе — ответ не уйдёт.
  canary: 'KB-57-CANARY',

  // Ключ для прогона evals: запрос с заголовком x-agent-debug, равным ему, получает в ответе
  // список вызванных инструментов. Пусто — режим выключен. Не кладите его на сайт.
  debug_token: '',
};

return [{ json: { config, input: $input.first().json } }];

// Guard In: проверяет вход до модели. Решает, кто отвечает: модель, заготовка или человек.
