  const fetch = TYPES[f.mimeType] || (/\.(md|txt)$/i.test(f.name) ? 'text' : null);
  if (!fetch) {
    skipped.push({ title: f.name, reason: `формат ${f.mimeType} не поддерживается` });
    continue;
  }
  plan.push({
    tool: 'extract_document',
    source_kind: 'drive',
    source_id: 'drive:' + f.id,
    drive_id: f.id,
    title: f.name.replace(/\.(pdf|md|txt)$/i, ''),
    url: f.webViewLink || `https://drive.google.com/file/d/${f.id}/view`,
    mime: f.mimeType,
    modified: f.modifiedTime || '',
    fetch,
  });
}

const yes = (v) => !/^(нет|no|false|0|off|выкл)$/i.test(String(v || '').trim());
const sourceRows = sourcesSheet.error ? [] : sheetRows(sourcesSheet.values).filter((r) => r.url);
for (const r of sourceRows) {
  if (!yes(r.enabled)) continue;
  if (!/^https?:\/\//i.test(r.url)) {
    skipped.push({ title: r.url, reason: 'ссылка должна начинаться с http:// или https://' });
    continue;
  }
  plan.push({
    tool: 'extract_document',
    source_kind: 'url',
    source_id: 'url:' + r.url,
    drive_id: '',
    title: r.title || r.url.replace(/^https?:\/\//, ''),
    url: r.url,
    mime: 'text/html',
    modified: '',
    fetch: 'url',
  });
}

plan.sort((a, b) => a.title.localeCompare(b.title, 'ru'));
const warnings = sourcesSheet.error ? ['Лист Sources не прочитан — ссылки не проиндексированы'] : [];
if (!plan.length) {
  // Пустой индекс — тоже результат: старые фрагменты удалятся.
  return [{ json: { empty: true, skipped, warnings } }];
}
return plan.map((p, i) => ({ json: { ...p, plan_index: i, skipped: i === 0 ? skipped : [], warnings: i === 0 ? warnings : [] } }));

// Build Docs: собирает тексты для индекса, присваивает документам коды d1, d2…
// и решает, можно ли перестраивать индекс.
const planned = $('Plan Sources').all().map((i) => i.json);
if (planned[0]?.abort) return [{ json: { abort: true, reason: planned[0].reason } }];

const results = $input.all().map((i) => i.json);
const docs = [];
const failed = [];
const skipped = planned[0]?.skipped || [];
const warnings = planned[0]?.warnings || [];

if (!planned[0]?.empty) {
  planned.forEach((p, i) => {
    const r = results[i] || {};
    if (r.ok) docs.push({ ...r, source_id: p.source_id, title: r.title || p.title, url: p.url, modified: p.modified });
    else failed.push({ title: p.title, url: p.url, reason: r.error || 'не удалось прочитать' });
  });
  if (!docs.length) {
    return [{ json: { abort: true, reason: `Ни один из ${planned.length} документов не прочитан — старый индекс оставлен как есть.`, failed } }];
  }
}

const summary = { docs: docs.length, failed, skipped, warnings };
if (!docs.length) {
  // Источников нет: индекс очищается, в нём остаётся одна пустая запись-заглушка.
  return [{ json: { abort: false, code: 'd0', tombstone: '1', source_id: '', title: '', url: '', modified: '', text: 'пустой индекс', summary } }];
}
return docs.map((d, i) => ({ json: { abort: false, code: 'd' + (i + 1), tombstone: '', ...d, summary: i === 0 ? summary : undefined } }));

// Registry: лист Documents после переиндексации — какие документы в индексе.
// Колонки: code | title | url | source_id | modified | chunks | chars | status | indexed_at
const built = $('Build Docs').all().map((i) => i.json);
const summary = built[0].summary;
const chunks = {};
for (const item of $input.all()) {
  const code = item.json.metadata?.code ?? item.json.document?.metadata?.code;
  if (code) chunks[code] = (chunks[code] || 0) + 1;
}
const now = new Date().toISOString();
const rows = [['code', 'title', 'url', 'source_id', 'modified', 'chunks', 'chars', 'status', 'indexed_at']];
for (const d of built.filter((b) => !b.tombstone)) {
  rows.push([d.code, d.title, d.url, d.source_id, d.modified, String(chunks[d.code] || 0), String(d.chars || 0), d.truncated ? 'обрезан' : 'ok', now]);
}
for (const f of summary.failed) rows.push(['', f.title, f.url || '', '', '', '0', '0', 'ошибка: ' + f.reason, now]);
for (const s of summary.skipped) rows.push(['', s.title, '', '', '', '0', '0', 'пропущен: ' + s.reason, now]);

// Старые строки ниже новых затираются пустыми.
const old = ($('Read Registry').first().json.values || []).length;
while (rows.length < old) rows.push(['', '', '', '', '', '', '', '', '']);
const total = Object.values(chunks).reduce((a, b) => a + b, 0);
return [{ json: { rows, total_chunks: built[0].tombstone ? 0 : total, summary } }];

